package com.feoearth.easybook;
import android.app.Activity;
import android.os.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.view.*;
import android.widget.*;

/** Platform PDF renderer: bounded bitmap, native scrolling, page controls and pinch zoom. */
public final class PdfActivity extends Activity {
 private PdfRenderer renderer;private ParcelFileDescriptor descriptor;private ImageView image;private TextView count;private int page=0;private float zoom=1;private Bitmap bitmap;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);LinearLayout bar=new LinearLayout(this);Button close=new Button(this),previous=new Button(this),next=new Button(this);close.setText("关闭");previous.setText("上一页");next.setText("下一页");count=new TextView(this);bar.addView(close);bar.addView(previous);bar.addView(count,new LinearLayout.LayoutParams(0,-2,1));bar.addView(next);layout.addView(bar);ScrollView vertical=new ScrollView(this);HorizontalScrollView horizontal=new HorizontalScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);horizontal.addView(image);vertical.addView(horizontal);layout.addView(vertical,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);close.setOnClickListener(v->finish());previous.setOnClickListener(v->{if(page>0){page--;zoom=1;render();}});next.setOnClickListener(v->{if(renderer!=null&&page+1<renderer.getPageCount()){page++;zoom=1;render();}});ScaleGestureDetector scale=new ScaleGestureDetector(this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){zoom=Math.max(1,Math.min(4,zoom*d.getScaleFactor()));resize();return true;}});image.setOnTouchListener((v,event)->{scale.onTouchEvent(event);if(event.getPointerCount()>1){v.getParent().requestDisallowInterceptTouchEvent(true);return true;}return false;});try{descriptor=getContentResolver().openFileDescriptor(getIntent().getData(),"r");renderer=new PdfRenderer(descriptor);if(renderer.getPageCount()==0)throw new Exception();render();}catch(Exception e){Toast.makeText(this,"无法预览此 PDF，请保存后使用其他应用打开",Toast.LENGTH_LONG).show();finish();}}
 private void resize(){if(bitmap!=null)image.setLayoutParams(new android.widget.FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*zoom),(int)(getResources().getDisplayMetrics().widthPixels*zoom*bitmap.getHeight()/bitmap.getWidth())));}
 private void render(){if(renderer==null)return;try(PdfRenderer.Page p=renderer.openPage(page)){int width=Math.min(1600,getResources().getDisplayMetrics().widthPixels*2),height=Math.max(1,(int)((long)width*p.getHeight()/p.getWidth()));if(height>4096){width=Math.max(1,width*4096/height);height=4096;}Bitmap next=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);next.eraseColor(Color.WHITE);p.render(next,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(next);if(bitmap!=null)bitmap.recycle();bitmap=next;resize();count.setText((page+1)+" / "+renderer.getPageCount());}}
 @Override protected void onDestroy(){if(renderer!=null)renderer.close();try{if(descriptor!=null)descriptor.close();}catch(Exception ignored){}if(bitmap!=null)bitmap.recycle();super.onDestroy();}
}
